@layer components {
  :where([data-control-family="alert"][data-slot="root"]) {
    --cui-alert-radius: var(--radius-lg);
    --cui-alert-background: var(--card);
    --cui-alert-border-color: var(--border);
    --cui-alert-shadow: none;
    --cui-alert-foreground: var(--card-foreground);
    --cui-alert-description-foreground: var(--muted-foreground);
    --cui-alert-border-width: 1px;
    --cui-alert-padding: calc(var(--spacing) * 3);
    --cui-alert-padding-inline: calc(var(--spacing) * 4);
    --cui-alert-gap: calc(var(--spacing) * 0.5);
    --cui-alert-icon-gap: calc(var(--spacing) * 3);
    --cui-alert-icon-size: calc(var(--spacing) * 4);
    --cui-alert-font-size: var(--text-sm);
    --cui-alert-title-font-weight: var(--font-weight-medium);
    --cui-alert-description-gap: var(--spacing);
    grid-template-columns: 0 minmax(0, 1fr);
    row-gap: var(--cui-alert-gap);
    padding: var(--cui-alert-padding) var(--cui-alert-padding-inline);
    border: var(--cui-alert-border-width) solid var(--cui-alert-border-color);
    border-radius: var(--cui-alert-radius);
    background: var(--cui-alert-background);
    box-shadow: var(--cui-alert-shadow);
    color: var(--cui-alert-foreground);
    font-size: var(--cui-alert-font-size);
    line-height: var(--text-sm--line-height);
    overflow-wrap: anywhere;
  }

  :where([data-control-family="alert"][data-slot="root"][data-variant="destructive"]) {
    --cui-alert-foreground: var(--destructive-text);
    --cui-alert-border-color: oklch(from var(--destructive) l c h / 0.5);
    --cui-alert-description-foreground: oklch(from var(--destructive-text) l c h / 0.9);
  }

  :where([data-control-family="alert"][data-slot="root"]:has(> svg)) {
    grid-template-columns: var(--cui-alert-icon-size) minmax(0, 1fr);
    column-gap: var(--cui-alert-icon-gap);
  }

  :where([data-control-family="alert"][data-slot="description"]) {
    gap: var(--cui-alert-description-gap);
    color: var(--cui-alert-description-foreground);
    font-size: var(--cui-alert-font-size);
    line-height: var(--text-sm--line-height);
  }

  :where([data-control-family="alert"][data-slot="description"] p) {
    line-height: var(--leading-relaxed);
  }

  :where([data-control-family="alert"][data-slot="title"]) {
    font-weight: var(--cui-alert-title-font-weight);
    letter-spacing: var(--tracking-tight);
  }

  :where([data-control-family="alert"][data-slot="root"] > svg) {
    color: currentcolor;
    inline-size: var(--cui-alert-icon-size);
    block-size: var(--cui-alert-icon-size);
    margin-block-start: max(0px, calc((1lh - var(--cui-alert-icon-size)) / 2));
  }
}

@property --cui-alert-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --cui-alert-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-alert-shadow {
  syntax: "*";
  inherits: true;
  initial-value: none;
}

@property --cui-alert-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-alert-description-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-alert-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-padding {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-padding-inline {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-icon-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-icon-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-font-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-description-gap {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-alert-title-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 500;
}

import type { ComponentProps, CSSProperties } from "react";
import type { AlertKnobStyle } from "@/components/control-ui/knob-contracts/alert-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export const alertVariants = ["default", "destructive"] as const;

export type AlertVariant = (typeof alertVariants)[number];

export type AlertProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & AlertKnobStyle } & { variant?: AlertVariant };

export type AlertTitleProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & AlertKnobStyle };

export type AlertDescriptionProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & AlertKnobStyle };

export function Alert({ variant = "default", className, ...props }: AlertProps) {
  return (
    <div
      role="alert"
      data-control-ui="alert"
      data-control-family="alert"
      data-slot="root"
      data-surface="panel"
      data-variant={variant}
      className={cn("relative grid w-full items-start", className)}
      {...props}
    />
  );
}

export function AlertTitle({ className, ...props }: AlertTitleProps) {
  return (
    <div
      data-control-ui="alert"
      data-control-family="alert"
      data-slot="title"
      className={cn("col-start-2 min-w-0", className)}
      {...props}
    />
  );
}

export function AlertDescription({ className, ...props }: AlertDescriptionProps) {
  return (
    <div
      data-control-ui="alert"
      data-control-family="alert"
      data-slot="description"
      className={cn("col-start-2 grid min-w-0 justify-items-start", className)}
      {...props}
    />
  );
}
